mkdir -p /app/output/assets && cat > /app/output/assets/styles.css <<'EOF'
:root {
  --bg: #0d1117;
  --bg-elev: #111827;
  --bg-elev-2: #161b22;
  --text: #e6edf3;
  --text-muted: #9da7b3;
  --border: #2f3a4a;
  --accent: #22d3ee;
  --accent-2: #22c55e;
  --card-glass: rgba(255, 255, 255, 0.03);
  --danger: #f87171;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: radial-gradient(circle at 10% 0%, #111a2a 0%, var(--bg) 40%);
  color: var(--text);
  min-height: 100vh;
  line-height: 1.55;
}

a { color: var(--accent); text-decoration: none; }
a:hover, a:focus-visible { text-decoration: underline; }

.container { width: min(1180px, 92vw); margin: 0 auto; }

.topbar {
  position: sticky; top: 0; z-index: 20;
  backdrop-filter: blur(10px);
  background: rgba(13, 17, 23, 0.85);
  border-bottom: 1px solid var(--border);
}
.topbar-inner { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; gap: 16px; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; letter-spacing: .2px; color: var(--text); }
.brand-badge {
  width: 28px; height: 28px; border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  display: inline-block;
}
.nav { display: flex; flex-wrap: wrap; gap: 12px; }
.nav a { color: var(--text-muted); padding: 8px 10px; border-radius: 8px; }
.nav a.active, .nav a:hover { color: var(--text); background: var(--card-glass); text-decoration: none; }

.hero { padding: 72px 0 40px; }
.hero h1 { font-size: clamp(2rem, 5vw, 3.2rem); margin: 0 0 12px; line-height: 1.1; }
.hero p { color: var(--text-muted); max-width: 760px; margin: 0 0 26px; }
.actions { display: flex; flex-wrap: wrap; gap: 12px; }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 11px 16px; border-radius: 10px; border: 1px solid var(--border);
  color: var(--text); background: var(--bg-elev-2); font-weight: 600;
}
.btn.primary { background: linear-gradient(90deg, #0891b2, #16a34a); border: none; color: #041014; }
.btn:hover { transform: translateY(-1px); transition: 160ms ease; text-decoration: none; }

.section { padding: 28px 0 20px; }
.section h2 { font-size: 1.4rem; margin: 0 0 14px; }
.section p.lead { color: var(--text-muted); margin-top: 0; }
.grid { display: grid; gap: 14px; }
.grid-3 { grid-template-columns: repeat(3, minmax(0,1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0,1fr)); }
.grid-2 { grid-template-columns: repeat(2, minmax(0,1fr)); }

.card {
  background: linear-gradient(180deg, var(--card-glass), rgba(255,255,255,0.01));
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
}
.card h3 { margin: 0 0 8px; font-size: 1.06rem; }
.card p { margin: 0 0 12px; color: var(--text-muted); }
.pill { display: inline-block; font-size: .75rem; border: 1px solid var(--border); border-radius: 999px; padding: 3px 8px; color: var(--text-muted); margin-bottom: 10px; }

.docs-layout { display: grid; grid-template-columns: 260px 1fr; gap: 20px; padding: 30px 0; }
.sidebar {
  border: 1px solid var(--border); border-radius: 14px; background: var(--bg-elev);
  padding: 14px; position: sticky; top: 72px; height: fit-content;
  transition: width .2s ease, padding .2s ease, opacity .2s ease;
}
.sidebar.collapsed { width: 72px; overflow: hidden; padding: 14px 10px; }
.sidebar h3 { font-size: .95rem; margin: 2px 0 10px; color: var(--text-muted); }
.sidebar ul { list-style: none; margin: 0; padding: 0; }
.sidebar li a { display: block; padding: 8px 10px; border-radius: 8px; color: var(--text-muted); }
.sidebar li a:hover { background: var(--card-glass); color: var(--text); text-decoration: none; }
.collapse-btn {
  width: 100%; margin-bottom: 10px; background: #0b1220; color: var(--text);
  border: 1px solid var(--border); border-radius: 10px; padding: 10px; cursor: pointer;
}
.main-doc { min-width: 0; }

.accordion-item { border: 1px solid var(--border); border-radius: 12px; margin-bottom: 10px; overflow: hidden; background: var(--bg-elev); }
.acc-btn {
  width: 100%; text-align: left; background: transparent; border: 0; color: var(--text);
  font-size: 1rem; padding: 14px; cursor: pointer;
}
.acc-panel { display: none; border-top: 1px solid var(--border); padding: 14px; }
.accordion-item.active .acc-panel { display: block; }

.tabs { display: inline-flex; border: 1px solid var(--border); border-radius: 10px; overflow: hidden; margin-bottom: 10px; }
.tab { background: #0b1220; color: var(--text-muted); border: 0; padding: 8px 12px; cursor: pointer; }
.tab.active { color: var(--text); background: #162235; }
pre {
  margin: 0; background: #05080f; border: 1px solid #1f2937; border-radius: 10px;
  padding: 12px; overflow-x: auto; color: #c9f7ff;
}
code { font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', monospace; font-size: .92rem; }

.footer { margin-top: 30px; padding: 26px 0 40px; color: var(--text-muted); border-top: 1px solid var(--border); }

@media (max-width: 980px) {
  .grid-4 { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .grid-3 { grid-template-columns: 1fr 1fr; }
  .docs-layout { grid-template-columns: 1fr; }
  .sidebar { position: relative; top: 0; }
}
@media (max-width: 700px) {
  .grid-3, .grid-2, .grid-4 { grid-template-columns: 1fr; }
  .hero { padding-top: 42px; }
}
EOF

cat > /app/output/assets/app.js <<'EOF'
(function () {
  const accordions = document.querySelectorAll('[data-accordion] .accordion-item');
  accordions.forEach((item) => {
    const btn = item.querySelector('.acc-btn');
    btn?.addEventListener('click', () => {
      accordions.forEach((other) => other.classList.remove('active'));
      item.classList.add('active');
    });
  });

  const tabGroups = document.querySelectorAll('[data-tabs]');
  tabGroups.forEach((group) => {
    const tabs = group.querySelectorAll('.tab');
    const code = group.querySelector('code[data-code]');
    tabs.forEach((tab) => {
      tab.addEventListener('click', () => {
        tabs.forEach((t) => t.classList.remove('active'));
        tab.classList.add('active');
        if (code) code.textContent = tab.dataset.command || '';
      });
    });
  });

  const sidebar = document.querySelector('[data-sidebar]');
  const collapseBtn = document.querySelector('[data-sidebar-toggle]');
  if (sidebar && collapseBtn) {
    const applyAuto = () => {
      if (window.innerWidth < 980) {
        sidebar.classList.add('collapsed');
        collapseBtn.setAttribute('aria-expanded', 'false');
      }
    };
    applyAuto();
    window.addEventListener('resize', applyAuto);
    collapseBtn.addEventListener('click', () => {
      sidebar.classList.toggle('collapsed');
      const expanded = !sidebar.classList.contains('collapsed');
      collapseBtn.setAttribute('aria-expanded', String(expanded));
    });
  }
})();
EOF

